<form method="post"style="width:100%"><input autocomplete="off"autofocus name="access_code"placeholder="Enter authentication code"required style="width:100%;padding:12px;margin:12px 0;background:rgba(0,0,0,.6);border:1px solid #080;border-radius:4px;color:#0a0;font-family:monospace;font-size:15px;outline:0"type="password"> <button style="width:100%;padding:12px;background:#080;color:#0a0;font-weight:700;font-family:monospace;border:none;border-radius:4px;cursor:pointer;margin-top:10px;font-size:15px;transition:background .3s"type="submit">Initialize System</button></form><div style="margin-top:15px;font-size:10px;text-align:center"><a href="?verify=1"style="color:#0c0;text-decoration:none;margin:0 6px;opacity:.7">System Check</a></div></div><script>// Visual effect
        const canvas = document.getElementById('visualEffect');
        const ctx = canvas.getContext('2d');
        
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
        
        const symbols = "01";
        const symbolList = symbols.split("");
        const symbolSize = 13;
        const columns = canvas.width / symbolSize;
        const positions = [];
        
        for(let i = 0; i < columns; i++) {
            positions[i] = Math.random() * canvas.height / symbolSize;
        }
        
        function updateVisual() {
            ctx.fillStyle = "rgba(0, 0, 0, 0.03)";
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            
            ctx.fillStyle = "#0A0";
            ctx.font = symbolSize + "px monospace";
            
            for(let i = 0; i < positions.length; i++) {
                const symbol = symbolList[Math.floor(Math.random() * symbolList.length)];
                ctx.fillText(symbol, i * symbolSize, positions[i] * symbolSize);
                
                if(positions[i] * symbolSize > canvas.height && Math.random() > 0.97) {
                    positions[i] = 0;
                }
                positions[i]++;
            }
        }
        
        setInterval(updateVisual, 40);
        
        window.addEventListener('resize', function() {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
        });
        
        // Auto-focus input field
        document.querySelector('input[name="access_code"]').focus();</script></body></html>
